<?php

namespace App\Services\Finance;

use Illuminate\Support\Facades\DB;

final class CorrectedInventoryService
{
    public static function build(string $prefix): array
    {
        $rows = DB::connection('mysql2')->select("SELECT x.reference,SUM(x.quantity) quantity,MAX(x.supplier_price) wholesale_price,MAX(x.currency) currency,MAX(x.conversion_rate) conversion_rate FROM (SELECT p.reference,sa.quantity,COALESCE(NULLIF(cp.wholesale_price_base_currency,0),p.wholesale_price,0) supplier_price,CASE WHEN COALESCE(NULLIF(cp.wholesale_price_base_currency,0),0)>0 THEN COALESCE(cur.iso_code,'EUR') ELSE 'EUR' END currency,CASE WHEN COALESCE(NULLIF(cp.wholesale_price_base_currency,0),0)>0 THEN COALESCE(cur.conversion_rate,1) ELSE 1 END conversion_rate FROM {$prefix}stock_available sa JOIN {$prefix}product p ON p.id_product=sa.id_product JOIN {$prefix}manufacturer m ON m.id_manufacturer=p.id_manufacturer LEFT JOIN {$prefix}custom_manufacturer cm ON cm.id_manufacturer=m.id_manufacturer LEFT JOIN {$prefix}custom_product cp ON cp.id_product=p.id_product LEFT JOIN {$prefix}currency cur ON cur.id_currency=cm.id_currency WHERE (sa.id_shop=0 OR (sa.id_shop IN (2,3) AND NOT EXISTS(SELECT 1 FROM {$prefix}stock_available sag0 WHERE sag0.id_product=sa.id_product AND sag0.id_product_attribute=sa.id_product_attribute AND sag0.id_shop=0))) AND EXISTS(SELECT 1 FROM {$prefix}product_shop pshop0 WHERE pshop0.id_product=p.id_product AND pshop0.id_shop IN (2,3)) AND sa.id_product_attribute=0 AND sa.quantity>0 AND p.reference<>'' AND NOT EXISTS(SELECT 1 FROM {$prefix}product_attribute pa0 WHERE pa0.id_product=p.id_product) AND NOT EXISTS(SELECT 1 FROM {$prefix}pack pk0 WHERE pk0.id_product_pack=p.id_product) UNION ALL SELECT pa.reference,sa.quantity,COALESCE(NULLIF(cpa.wholesale_price_base_currency,0),NULLIF(cp.wholesale_price_base_currency,0),pa.wholesale_price,p.wholesale_price,0),CASE WHEN COALESCE(NULLIF(cp.wholesale_price_base_currency,0),0)>0 THEN COALESCE(cur.iso_code,'EUR') ELSE 'EUR' END,CASE WHEN COALESCE(NULLIF(cpa.wholesale_price_base_currency,0),NULLIF(cp.wholesale_price_base_currency,0),0)>0 THEN COALESCE(cur.conversion_rate,1) ELSE 1 END FROM {$prefix}stock_available sa JOIN {$prefix}product_attribute pa ON pa.id_product_attribute=sa.id_product_attribute JOIN {$prefix}product p ON p.id_product=sa.id_product JOIN {$prefix}manufacturer m ON m.id_manufacturer=p.id_manufacturer LEFT JOIN {$prefix}custom_manufacturer cm ON cm.id_manufacturer=m.id_manufacturer LEFT JOIN {$prefix}custom_product cp ON cp.id_product=p.id_product LEFT JOIN {$prefix}custom_product_attribute cpa ON cpa.id_product_attribute=pa.id_product_attribute LEFT JOIN {$prefix}currency cur ON cur.id_currency=cm.id_currency WHERE (sa.id_shop=0 OR (sa.id_shop IN (2,3) AND NOT EXISTS(SELECT 1 FROM {$prefix}stock_available sag1 WHERE sag1.id_product=sa.id_product AND sag1.id_product_attribute=sa.id_product_attribute AND sag1.id_shop=0))) AND EXISTS(SELECT 1 FROM {$prefix}product_shop pshop1 WHERE pshop1.id_product=p.id_product AND pshop1.id_shop IN (2,3)) AND sa.id_product_attribute>0 AND sa.quantity>0 AND pa.reference<>'' AND NOT EXISTS(SELECT 1 FROM {$prefix}pack pk1 WHERE pk1.id_product_pack=p.id_product)) x GROUP BY x.reference ORDER BY x.reference");
        $data=[];
        foreach($rows as $row){$price=(float)$row->wholesale_price;$rate=(float)$row->conversion_rate;if($rate<=0)$rate=1.0;$eur=$price/$rate;$qty=(int)$row->quantity;$data[(string)$row->reference]=(object)['reference'=>(string)$row->reference,'quantity'=>$qty,'wholesale_price'=>$price,'currency'=>(string)$row->currency,'eur_convertion'=>$eur,'total_row'=>$qty*$eur];}
        return $data;
    }
}
